-- Idempotent install for metrics.custom_metrics
-- Auto-generated from dbanalytics_install.backup. Safe to re-run (psql -f).

CREATE SCHEMA IF NOT EXISTS metrics;

CREATE SEQUENCE IF NOT EXISTS metrics.custom_metrics_row_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE IF NOT EXISTS metrics.custom_metrics (
    row_id integer NOT NULL,
    category_id integer NOT NULL,
    metric_name character varying(255) NOT NULL,
    query text NOT NULL,
    description text NOT NULL,
    entry_date timestamp without time zone DEFAULT now() NOT NULL,
    is_active boolean,
    db_vendor character varying(50) DEFAULT 'MSSQL'::character varying NOT NULL,
    metrics_type public.metric_type DEFAULT 'collect'::public.metric_type NOT NULL
);

ALTER TABLE metrics.custom_metrics ALTER COLUMN row_id SET DEFAULT nextval('metrics.custom_metrics_row_id_seq'::regclass);
ALTER SEQUENCE metrics.custom_metrics_row_id_seq OWNED BY metrics.custom_metrics.row_id;

-- data: load only into a freshly-created (empty) table
DROP TABLE IF EXISTS _stg_load;
CREATE TEMP TABLE _stg_load (LIKE metrics.custom_metrics);
SELECT row_id, category_id, metric_name, query, description, entry_date, is_active, db_vendor, metrics_type FROM _stg_load
WHERE NOT EXISTS (SELECT 1 FROM metrics.custom_metrics);
DROP TABLE _stg_load;

SELECT setval('metrics.custom_metrics_row_id_seq', GREATEST((SELECT COALESCE(max(row_id),0) FROM metrics.custom_metrics),1), (SELECT count(*) FROM metrics.custom_metrics) > 0);

DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint con
        JOIN pg_class c ON c.oid = con.conrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'metrics' AND c.relname = 'custom_metrics'
          AND con.conname = 'custom_metrics_pkey') THEN
        ALTER TABLE ONLY metrics.custom_metrics
    ADD CONSTRAINT custom_metrics_pkey PRIMARY KEY (row_id);
    END IF;
END $do$;
